mapper.select:
SELECT id, member_id, idempotency_key, request_hash, order_id, status, create_time, update_time
FROM oms_order_idempotency
WHERE member_id = #{memberId}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.update:
UPDATE oms_order_idempotency
SET order_id = #{orderId},
    status = 'SUCCESS',
    update_time = NOW()
WHERE member_id = #{memberId}
  AND idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = 'PROCESSING'

UPDATE pms_sku_stock
SET lock_stock = GREATEST(COALESCE(lock_stock, 0), 0) + #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(stock, 0) >= 0
  AND COALESCE(stock, 0) - GREATEST(COALESCE(lock_stock, 0), 0) >= #{quantity}

UPDATE pms_sku_stock
SET stock = COALESCE(stock, 0) - #{quantity},
    lock_stock = COALESCE(lock_stock, 0) - #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(stock, 0) >= #{quantity}
  AND COALESCE(lock_stock, 0) >= #{quantity}

UPDATE pms_sku_stock
SET lock_stock = COALESCE(lock_stock, 0) - #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(lock_stock, 0) >= #{quantity}
